export const EMBEDDED_HTML = "<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"description\" content=\"Restream Panel — RTMP restream server configuration dashboard\" />\r\n    <title>Restream Panel</title>\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\r\n    <link\r\n      href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500;600&display=swap\"\r\n      rel=\"stylesheet\"\r\n    />\r\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\r\n  </head>\r\n  <body>\r\n    <div id=\"app\"></div>\r\n    <script type=\"module\" src=\"/main.js\"></script>\r\n  </body>\r\n</html>\r\n";
export const EMBEDDED_CSS = "/* Fonts load via <link> in index.html (single request chain). */\r\n:root {\r\n  --bg-void: #09090b;\r\n  --bg-panel: #0d0d10;\r\n  --bg-card: #111114;\r\n\r\n  --accent: #00ff88;\r\n  --accent-text: #00331b;\r\n\r\n  --text-main: #f4f4f5;\r\n  --text-muted: #a1a1aa;\r\n  --faint: #6b6b76;\r\n\r\n  --danger: #ef4444;\r\n  --warning: #f59e0b;\r\n  --success: #00ff88;\r\n  --good: #00ff88;\r\n\r\n  --border: #27272a;\r\n  --border-subtle: #1b1b1f;\r\n\r\n  --font-sans: \"Public Sans\", system-ui, -apple-system, sans-serif;\r\n  --font-display: \"Public Sans\", system-ui, -apple-system, sans-serif;\r\n  --font-mono: \"JetBrains Mono\", monospace;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  font-family: var(--font-sans);\r\n  background-color: var(--bg-void);\r\n  color: var(--text-main);\r\n  min-height: 100vh;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\n/* Animations */\r\n@keyframes fadeIn {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(10px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\n@keyframes pulse {\r\n  0% {\r\n    box-shadow: 0 0 0 0 rgba(0, 255, 136, 0.2);\r\n  }\r\n  70% {\r\n    box-shadow: 0 0 0 6px rgba(0, 255, 136, 0);\r\n  }\r\n  100% {\r\n    box-shadow: 0 0 0 0 rgba(0, 255, 136, 0);\r\n  }\r\n}\r\n\r\n/* Layout */\r\n.header {\r\n  border-bottom: 1px solid var(--border);\r\n  background: rgba(9, 9, 11, 0.9);\r\n  backdrop-filter: blur(12px);\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 100;\r\n}\r\n\r\n.container {\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 1.5rem;\r\n}\r\n\r\n.header-content {\r\n  height: 60px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n.header-brand {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n}\r\n\r\n.header-logo {\r\n  color: var(--accent);\r\n  width: 26px;\r\n  height: 26px;\r\n}\r\n\r\nh1 {\r\n  font-family: var(--font-display);\r\n  font-weight: 600;\r\n  margin: 0;\r\n  font-size: 1.05rem;\r\n  letter-spacing: 0;\r\n}\r\n\r\n:focus-visible {\r\n  outline: 2px solid var(--accent);\r\n  outline-offset: 2px;\r\n}\r\n\r\n.header-meta {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.header-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1.5rem;\r\n}\r\n\r\n.status-badge {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.375rem 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.status-badge.running {\r\n  border-color: rgba(0, 255, 136, 0.3);\r\n  color: var(--accent);\r\n}\r\n\r\n.status-badge.stale {\r\n  border-color: rgba(245, 158, 11, 0.4);\r\n  color: var(--warning);\r\n}\r\n\r\n.status-badge.stale .status-dot {\r\n  background: var(--warning);\r\n}\r\n\r\n.status-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  background: var(--text-muted);\r\n}\r\n\r\n.status-badge.running .status-dot {\r\n  background: var(--accent);\r\n  animation: pulse 2s infinite;\r\n}\r\n\r\n/* Version badge */\r\n.version-badge {\r\n  padding: 0.375rem 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  letter-spacing: 0.05em;\r\n  color: var(--text-muted);\r\n  text-transform: lowercase;\r\n}\r\n\r\n/* Toolbar */\r\n.toolbar {\r\n  margin: 1.25rem 0;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.toolbar-info {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n}\r\n\r\n/* Application Cards — flat hairline surfaces, no lifted slabs. */\r\n.card {\r\n  background: var(--bg-card);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  padding: 1.25rem;\r\n  margin-bottom: 1rem;\r\n  position: relative;\r\n  overflow: hidden;\r\n  animation: fadeIn 0.4s ease backwards;\r\n}\r\n\r\n.card-title {\r\n  font-family: var(--font-display);\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  letter-spacing: -0.01em;\r\n}\r\n\r\n.card-subtitle {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  margin-top: 0.25rem;\r\n}\r\n\r\n/* Components */\r\n.btn {\r\n  border: none;\r\n  border-radius: 6px;\r\n  padding: 0.5rem 1rem;\r\n  font-family: var(--font-display);\r\n  font-weight: 600;\r\n  font-size: 0.875rem;\r\n  cursor: pointer;\r\n  transition: background-color 0.15s ease, border-color 0.15s ease;\r\n}\r\n\r\n.btn:active {\r\n  transform: scale(0.97);\r\n}\r\n\r\n.btn-primary {\r\n  background: var(--accent);\r\n  color: var(--accent-text);\r\n}\r\n\r\n.btn-primary:hover {\r\n  background: #33ff99;\r\n}\r\n\r\n/* Form */\r\n.form-group {\r\n  padding: 1.5rem;\r\n}\r\n\r\n.form-label {\r\n  display: block;\r\n  font-family: var(--font-display);\r\n  font-weight: 500;\r\n  font-size: 0.875rem;\r\n  margin-bottom: 0.5rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.form-input {\r\n  width: 100%;\r\n  background: var(--bg-void);\r\n  border: 1px solid var(--border);\r\n  padding: 0.75rem;\r\n  color: var(--text-main);\r\n  font-family: var(--font-mono);\r\n  font-size: 0.875rem;\r\n  border-radius: 4px;\r\n}\r\n\r\n.form-input:focus {\r\n  outline: none;\r\n  border-color: var(--accent);\r\n  box-shadow: 0 0 0 1px rgba(0, 255, 136, 0.4);\r\n}\r\n\r\n.form-input.valid {\r\n  border-color: var(--success);\r\n}\r\n.form-input.invalid {\r\n  border-color: var(--danger);\r\n}\r\n\r\n/* Alert */\r\n.alert {\r\n  padding: 1rem 1.5rem;\r\n  border-radius: 4px;\r\n  margin-bottom: 1.5rem;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n  animation: fadeIn 0.3s ease;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.875rem;\r\n}\r\n\r\n.alert-success {\r\n  background: rgba(0, 255, 136, 0.1);\r\n  border: 1px solid var(--success);\r\n  color: var(--success);\r\n}\r\n.alert-error {\r\n  background: rgba(239, 68, 68, 0.1);\r\n  border: 1px solid var(--danger);\r\n  color: var(--danger);\r\n}\r\n.alert-warning {\r\n  background: rgba(245, 158, 11, 0.1);\r\n  border: 1px solid var(--warning);\r\n  color: var(--warning);\r\n}\r\n\r\n.alert-close {\r\n  margin-left: auto;\r\n  background: none;\r\n  border: none;\r\n  color: currentColor;\r\n  opacity: 0.7;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Scrollbar */\r\n::-webkit-scrollbar {\r\n  width: 8px;\r\n}\r\n\r\n::-webkit-scrollbar-track {\r\n  background: var(--bg-void);\r\n}\r\n\r\n::-webkit-scrollbar-thumb {\r\n  background: var(--border);\r\n  border-radius: 4px;\r\n}\r\n\r\n::-webkit-scrollbar-thumb:hover {\r\n  background: var(--text-muted);\r\n}\r\n\r\n/* Health */\r\n.health-page {\r\n  padding-top: 1.5rem;\r\n  padding-bottom: 3rem;\r\n}\r\n\r\n.health-toolbar {\r\n  gap: 1rem;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.health-card {\r\n  padding-left: 1.5rem;\r\n  padding-right: 1.5rem;\r\n}\r\n\r\n.health-status-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  gap: 1rem;\r\n  margin-bottom: 1.25rem;\r\n}\r\n\r\n.health-table-wrap {\r\n  overflow-x: auto;\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  background: var(--bg-panel);\r\n}\r\n\r\n.health-table {\r\n  width: 100%;\r\n  table-layout: fixed;\r\n  border-collapse: collapse;\r\n  min-width: 880px;\r\n}\r\n\r\n.health-table th,\r\n.health-table td {\r\n  padding: 0.55rem 0.6rem;\r\n  text-align: right;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.04);\r\n  vertical-align: middle;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.health-table th:nth-child(1),\r\n.health-table th:nth-child(2),\r\n.health-table td:nth-child(1),\r\n.health-table td:nth-child(2) {\r\n  text-align: left;\r\n}\r\n\r\n.health-table th {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.6875rem;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--text-muted);\r\n  background: rgba(255, 255, 255, 0.02);\r\n  position: sticky;\r\n  top: 0;\r\n}\r\n\r\n.health-table tbody tr:hover {\r\n  background: rgba(255, 255, 255, 0.02);\r\n}\r\n\r\n.health-table tbody tr:last-child td {\r\n  border-bottom: none;\r\n}\r\n\r\n.health-mono {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n}\r\n\r\n/* Identity columns (target/proto/health) are plain colored code text —\r\n   the hex matches the chart series stroke, no badge chrome. */\r\n.cell-code {\r\n  font-weight: 600;\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.health-col-target {\r\n  width: 8.5%;\r\n}\r\n\r\n.health-col-proto {\r\n  width: 4.5%;\r\n}\r\n\r\n.health-col-health {\r\n  width: 6%;\r\n}\r\n\r\n.health-col-peer {\r\n  width: 16%;\r\n}\r\n\r\n.health-col-rate {\r\n  width: 7%;\r\n}\r\n\r\n.health-col-bytes {\r\n  width: 11%;\r\n}\r\n\r\n.health-col-rtt {\r\n  width: 8%;\r\n}\r\n\r\n.health-col-queue {\r\n  width: 6%;\r\n}\r\n\r\n.health-col-retrans {\r\n  width: 10%;\r\n}\r\n\r\n.health-empty {\r\n  text-align: center;\r\n  color: var(--text-muted);\r\n  font-family: var(--font-mono);\r\n  letter-spacing: 0.04em;\r\n}\r\n\r\n.health-hidden {\r\n  display: none;\r\n}\r\n\r\n.text-good {\r\n  color: var(--accent) !important;\r\n}\r\n.text-warn {\r\n  color: #fbbf24 !important;\r\n}\r\n.text-bad {\r\n  color: #f87171 !important;\r\n}\r\n\r\n/* Stream plaque — on-air header: tally dot, identity, live numbers. */\r\n.stream-plaque {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.9rem;\r\n}\r\n\r\n.plaque-dot {\r\n  width: 12px;\r\n  height: 12px;\r\n  border-radius: 50%;\r\n  flex-shrink: 0;\r\n  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.plaque-main {\r\n  flex: 1;\r\n  min-width: 0;\r\n}\r\n\r\n.plaque-main .stream-title {\r\n  font-size: 1.1rem;\r\n}\r\n\r\n.plaque-stats {\r\n  text-align: right;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.plaque-bitrate {\r\n  font-family: var(--font-mono);\r\n  font-size: 1.4rem;\r\n  font-weight: 600;\r\n  line-height: 1.1;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.plaque-cap {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  letter-spacing: 0.06em;\r\n  text-transform: uppercase;\r\n  color: var(--text-muted);\r\n}\r\n\r\n/* Stream identity: left-aligned title + single meta line (was a centered subtitle). */\r\n.stream-head {\r\n  margin-bottom: 1rem;\r\n}\r\n\r\n.stream-title {\r\n  font-family: var(--font-display);\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  margin: 0 0 0.25rem;\r\n  letter-spacing: 0;\r\n  text-wrap: balance;\r\n}\r\n\r\n.stream-meta {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  color: var(--text-muted);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.stream-subhead {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--faint);\r\n  margin: 1.25rem 0 0.5rem;\r\n}\r\n\r\n/* Toolbar stats */\r\n.stat-group {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1.25rem;\r\n}\r\n\r\n.stat {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  letter-spacing: 0.06em;\r\n  text-transform: uppercase;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.stat b {\r\n  color: var(--text-main);\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n  margin-left: 0.35rem;\r\n}\r\n\r\n/* Event stream — inset console: dark well, severity accent bar, dense rows. */\r\n.event-log-card {\r\n  padding: 1.25rem 1.25rem 1rem;\r\n  background: #0b0b0e;\r\n}\r\n\r\n.log-head {\r\n  margin-bottom: 0.9rem;\r\n}\r\n\r\n.log-filters {\r\n  margin-bottom: 0.75rem;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.event-log-container {\r\n  max-height: 380px;\r\n  overflow-y: auto;\r\n  overflow-x: auto;\r\n  border-top: 1px solid var(--border-subtle);\r\n  padding: 0.4rem 0;\r\n}\r\n\r\n.event-log-entry {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 1rem;\r\n  padding: 0.28rem 1rem 0.28rem calc(1rem - 2px);\r\n  border-left: 2px solid transparent;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  line-height: 1.6;\r\n  white-space: nowrap;\r\n}\r\n\r\n.event-log-entry:hover {\r\n  background: rgba(255, 255, 255, 0.03);\r\n}\r\n\r\n.event-log-entry.sev-up {\r\n  border-left-color: var(--good);\r\n}\r\n\r\n.event-log-entry.sev-down {\r\n  border-left-color: var(--danger);\r\n}\r\n\r\n.event-log-entry.sev-degraded {\r\n  border-left-color: var(--warning);\r\n}\r\n\r\n.event-log-timestamp {\r\n  color: var(--faint);\r\n  font-variant-numeric: tabular-nums;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-type {\r\n  font-weight: 600;\r\n  width: 190px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-stream {\r\n  color: var(--text-main);\r\n  font-weight: 600;\r\n  max-width: 220px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-detail {\r\n  flex-grow: 1;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.event-type-connected {\r\n  color: var(--accent);\r\n}\r\n\r\n.event-type-disconnected {\r\n  color: var(--danger);\r\n}\r\n\r\n.event-type-degraded {\r\n  color: var(--warning);\r\n}\r\n\r\n/* uPlot Base & Bandwidth Chart */\r\n.uplot, .uplot *, .uplot *::before, .uplot *::after {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.uplot {\r\n  font-family: var(--font-mono);\r\n  line-height: 1.5;\r\n  width: 100%;\r\n  position: relative;\r\n  user-select: none;\r\n}\r\n\r\n.u-wrap {\r\n  position: relative;\r\n  user-select: none;\r\n}\r\n\r\n.u-over, .u-under {\r\n  position: absolute;\r\n}\r\n\r\n.u-under {\r\n  overflow: hidden;\r\n}\r\n\r\n.uplot canvas {\r\n  display: block;\r\n  position: relative;\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n.u-axis {\r\n  position: absolute;\r\n}\r\n\r\n.u-select {\r\n  background: rgba(0, 255, 136, 0.12);\r\n  border-left: 1px solid var(--accent);\r\n  border-right: 1px solid var(--accent);\r\n  position: absolute;\r\n  pointer-events: none;\r\n}\r\n\r\n.u-cursor-x, .u-cursor-y {\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  pointer-events: none;\r\n  will-change: transform;\r\n}\r\n\r\n.u-hz .u-cursor-x, .u-vt .u-cursor-y {\r\n  height: 100%;\r\n  border-right: 1px dashed rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n.u-hz .u-cursor-y, .u-vt .u-cursor-x {\r\n  width: 100%;\r\n  border-bottom: 1px dashed rgba(255, 255, 255, 0.15);\r\n}\r\n\r\n.u-cursor-pt {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  border-radius: 50%;\r\n  border: 0 solid;\r\n  pointer-events: none;\r\n  will-change: transform;\r\n  background-clip: padding-box !important;\r\n}\r\n\r\n.u-axis.u-off, .u-select.u-off, .u-cursor-x.u-off, .u-cursor-y.u-off, .u-cursor-pt.u-off {\r\n  display: none;\r\n}\r\n\r\n.stream-chart-card {\r\n  margin-top: 0.75rem;\r\n  padding: 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  position: relative;\r\n}\r\n\r\n.stream-chart-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 0.5rem;\r\n  flex-wrap: wrap;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.stream-chart-eyebrow {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.65rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--faint);\r\n}\r\n\r\n.stream-chart-legend-val {\r\n  color: var(--text-main);\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n\r\n.stream-chart-legend {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.stream-chart-legend-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.35rem;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.stream-chart-legend-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  display: inline-block;\r\n}\r\n\r\n.stream-chart-legend-label {\r\n  color: var(--text-main);\r\n  opacity: 0.85;\r\n}\r\n\r\n.stream-chart-controls {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.chart-btn-group {\r\n  display: inline-flex;\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  overflow: hidden;\r\n  background: var(--bg-void);\r\n}\r\n\r\n.chart-btn {\r\n  background: transparent;\r\n  border: none;\r\n  color: var(--text-muted);\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  padding: 0.2rem 0.5rem;\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.chart-btn:hover {\r\n  color: var(--text-main);\r\n  background: rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.chart-btn.active {\r\n  background: var(--accent);\r\n  color: var(--accent-text);\r\n  font-weight: 600;\r\n}\r\n\r\n.chart-live-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.35rem;\r\n  padding: 0.2rem 0.6rem;\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  font-weight: 600;\r\n  border: 1px solid transparent;\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.chart-live-btn.live-active {\r\n  background: rgba(0, 255, 136, 0.12);\r\n  border-color: rgba(0, 255, 136, 0.3);\r\n  color: var(--accent);\r\n}\r\n\r\n.chart-live-btn.live-paused {\r\n  background: var(--warning);\r\n  border-color: var(--warning);\r\n  color: #231303;\r\n}\r\n\r\n.chart-live-dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: currentColor;\r\n}\r\n\r\n.chart-live-btn.live-active .chart-live-dot {\r\n  animation: pulse 2s infinite;\r\n}\r\n\r\n.stream-chart-plot-wrap {\r\n  position: relative;\r\n  width: 100%;\r\n  min-height: 220px;\r\n}\r\n\r\n.uplot-wrapper {\r\n  width: 100%;\r\n  height: 220px;\r\n}\r\n\r\n.chart-tooltip {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  pointer-events: none;\r\n  z-index: 10;\r\n  background: rgba(18, 18, 20, 0.94);\r\n  backdrop-filter: blur(8px);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  padding: 0.5rem 0.75rem;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6);\r\n  will-change: transform;\r\n  min-width: 150px;\r\n}\r\n\r\n.chart-tooltip-time {\r\n  color: var(--text-muted);\r\n  font-size: 0.68rem;\r\n  margin-bottom: 0.35rem;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\r\n  padding-bottom: 0.2rem;\r\n}\r\n\r\n.chart-tooltip-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.4rem;\r\n  margin-top: 0.2rem;\r\n  white-space: nowrap;\r\n}\r\n\r\n.chart-tooltip-dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  display: inline-block;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.chart-tooltip-name {\r\n  color: var(--text-muted);\r\n  flex: 1;\r\n}\r\n\r\n.chart-tooltip-val {\r\n  color: var(--text-main);\r\n  font-weight: 600;\r\n  text-align: right;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 640px) {\r\n  .header-actions span {\r\n    display: none;\r\n  }\r\n  .health-status-row {\r\n    flex-direction: column;\r\n  }\r\n  .health-card {\r\n    padding-left: 1rem;\r\n    padding-right: 1rem;\r\n  }\r\n  .stream-chart-header {\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n  }\r\n}\r\n\r\n";
